window.__votdWeek && window.__votdWeek({"week":"2029-11-26","reading":"Doctrine and Covenants 135–136","days":[{"d":"2029-11-26","ref":"D&C 136:21","b":"D&C","c":136,"v":21,"he":"הִשָּׁמְרוּ מֵרַע לָשְׂאֵת אֶת־שֵׁם־יְהוָה לַשָּׁוְא כִּי אֲנִי יְהוָה אֱלֹהֵיכֶם גַּם אֱלֹהֵי אֲבוֹתֵיכֶם אֱלֹהֵי אַבְרָהָם וְיִצְחָק וְיַעֲקֹב׃","en":"Keep yourselves from evil to take the name of the Lord in vain, for I am the Lord your God, even the God of your fathers, the God of Abraham and of Isaac and of Jacob."},{"d":"2029-11-27","ref":"D&C 136:22","b":"D&C","c":136,"v":22,"he":"אֲנִי הוּא אֲשֶׁר הוֹצֵאתִי אֶת־בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם וּזְרוֹעִי נְטוּיָה בְּאַחֲרִית הַיָּמִים לְהוֹשִׁיעַ אֶת־עַמִּי יִשְׂרָאֵל׃","en":"I am he who led the children of Israel out of the land of Egypt; and my arm is stretched out in the last days, to save my people Israel."},{"d":"2029-11-28","ref":"D&C 136:23","b":"D&C","c":136,"v":23,"he":"חִדְלוּ לָרִיב אִישׁ בְּרֵעֵהוּ חִדְלוּ לְדַבֵּר רָע אִישׁ עַל רֵעֵהוּ׃","en":"Cease to contend one with another; cease to speak evil one of another."},{"d":"2029-11-29","ref":"D&C 136:26","b":"D&C","c":136,"v":26,"he":"אִם תִּמְצָא אֲבֵדַת רֵעֶךָ תְּחַפֵּשׂ הֵיטֵב עַד הֲשִׁיבְךָ אוֹתָהּ לוֹ׃","en":"If thou shalt find that which thy neighbor has lost, thou shalt make diligent search till thou shalt deliver it to him again."},{"d":"2029-11-30","ref":"D&C 136:28","b":"D&C","c":136,"v":28,"he":"אִם טוֹב לְבָבְךָ הַלֵּל אֶת־יְהוָה בְּשִׁירָה וּבִנְגִינָה בְּמָחוֹל וּבִתְפִלַּת תְּהִלָּה וְתוֹדָה׃","en":"If thou art merry, praise the Lord with singing, with music, with dancing, and with a prayer of praise and thanksgiving."},{"d":"2029-12-01","ref":"D&C 136:31","b":"D&C","c":136,"v":31,"he":"עַמִּי יְנֻסֶּה בְּכֹל לְמַעַן יִהְיוּ מוּכָנִים לְקַבֵּל אֶת־הַכָּבוֹד אֲשֶׁר יֶשׁ־לִי לָהֶם גַּם כְּבוֹד צִיּוֹן וַאֲשֶׁר לֹא יִשָּׂא מוּסָר אֵינוֹ רָאוּי לְמַלְכוּתִי׃","en":"My people must be tried in all things, that they may be prepared to receive the glory that I have for them, even the glory of Zion; and he that will not bear chastisement is not worthy of my kingdom."},{"d":"2029-12-02","ref":"D&C 136:36","b":"D&C","c":136,"v":36,"he":"כִּי הָרְגוּ אֶת־הַנְּבִיאִים וְאֶת הַשְּׁלוּחִים אֲלֵיהֶם וְשָׁפְכוּ דָם נָקִי אֲשֶׁר צֹעֵק מִן הָאֲדָמָה עֲלֵיהֶם׃","en":"For they killed the prophets, and them that were sent unto them; and they have shed innocent blood, which crieth from the ground against them."}]});
